def step(context):
    import json
    plan = context['inputs']['plans'][0]['payload']
    world = context['inputs']['world'][0]['payload']
    year = context['period']
    active = {a['id'] for a in world['ecosystem']['agents'] if a['can_author'] and a['is_active']}
    amendments = []
    for original in plan['assignments']:
        if original['actor_id'] not in active:
            continue
        assignment = json.loads(json.dumps(original))
        assignment['direction']['years'] = 1
        assignment['project_start_year'] = year
        assignment['project_end_year'] = year
        assignment['detailed_focus'] = original['detailed_focus'] + ' Annual scope: produce a complete, narrow native manuscript this year; retain the chosen topic and original evidence.'
        assignment['reason'] = original['reason'] + ' Institution schedules an annual publication window.'
        amendments.append({'payload':{'schema':'native-research-amendment-v1','target_year':year,
            'assignment':assignment,'submit':True}})
    return {'outputs':{'amendments':amendments},'state':{'cycles':context['state'].get('cycles',0)+1,
        'last_year':year,'scheduled_actor_ids':sorted(active)}}

